import numpy as np

def signal(obs):
    out = {}
    for a in obs.mid:
        tr = obs.trades[a][-50:]
        if len(tr) < 10:
            out[a] = 0.0
            continue
        flow = sum(q * s for _, q, s in tr)
        vol = sum(q for _, q, _ in tr) + 1e-9
        out[a] = float(np.clip(2.0 * flow / vol, -1, 1))
    return out

