import numpy as np

def signal(obs):
    out = {}
    for a in obs.mid:
        bids, asks = obs.depth[a]
        b = sum(q for _, q in bids[:5])
        s = sum(q for _, q in asks[:5])
        imb = (b - s) / (b + s + 1e-9)
        # only act on strong pressure
        if abs(imb) < 0.35:
            out[a] = obs.position[a] * 0.5
        else:
            out[a] = float(np.tanh(3.0 * imb))
    return out

def signal(obs):
    out = {}
    for a in obs.mid:
        h = obs.hist(a, 'mid', 100)
        if len(h) < 100:
            out[a] = 0.0
            continue
        hi, lo = max(h[:-1]), min(h[:-1])
        m = h[-1]
        out[a] = 1.0 if m > hi else (-1.0 if m < lo else 0.0)
    return out
